const _DTH={"waterbox":{"thumb":"https://res.cloudinary.com/dirsjev28/video/upload/v1788666568/portfolio/tools/1_yx6vzi.mov","desc":"A motion graphic tool inspired by children’s water-filled toy boxes. Shapes transform into frames, while typography moves within the watery environment, mimicking its distinctive bounce and fluid motion.","url":""},"curtain":{"thumb":"https://res.cloudinary.com/dirsjev28/video/upload/v1788667163/portfolio/tools/2_o0cfvi.mov","desc":"A motion graphic tool inspired by flowing curtains. Typography and imagery can be applied as decorative elements, with their movement responding to the rhythm and direction of the cursor","url":""},"imagegrid":{"desc":"A motion graphic tool that generates typography from images. Users can upload one or multiple images to create text-based visuals.","url":"","thumb":"https://res.cloudinary.com/dirsjev28/video/upload/v1788666839/portfolio/tools/3_vxjuev.mov"},"dust":{"desc":"A motion graphics tool where organic cell patterns grow and breathe inside your text. Cells fill the letterforms, respond to your mouse, and can be exported as PNG, SVG, or video the moment you like what you see.","url":"","thumb":"https://res.cloudinary.com/dirsjev28/video/upload/v1788666578/portfolio/tools/4_juhzuj.mov"}};
